#################GAME OVER MUSIC########################
    game_over_times: .word 0, 0, 400, 400, 800, 800, 1100, 1100, 1333, 1566, 1800, 1800, 2100, 2400, 2700, 2700, 2850, 2850, 3000, 3000, 0, 0, 400, 400, 800, 800, 1100, 1100, 1800, 1800, 2700, 2700
