    game_over_velocity: .word 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100, 100
    game_over_duration: .word 200, 200, 200, 200, 300, 300, 230, 230, 233, 700, 300, 300, 300, 900, 150, 150, 150, 150, 1800, 1800, 200, 200, 200, 200, 300, 300, 693, 693, 950, 950, 2100, 2100
    game_over_instruments: .word 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74, 74
    game_over_noteCount: .word 32
    game_over_lastTime: .word 0
##############################################################################
# Mutable Data
##############################################################################
# Current capsule position and orientation
CAPSULE_POS_X1:
    .word 31    # First half X position
CAPSULE_POS_Y1:
    .word 18     # First half Y position
CAPSULE_POS_X2:
    .word 32    # Second half X position
CAPSULE_POS_Y2:
    .word 18     # Second half Y position
CAPSULE_ORIENTATION:
    .word 0     # 0: horizontal right, 1: vertical down, 2: horizontal left, 3: vertical up
SLEEP_TIME:
    .word 1  # Sleep time in milliseconds (1 second)
CURRENT_COLOR_1:
    .word 0x000000    # Current color for first half
CURRENT_COLOR_2:
    .word 0x000000    # Current color for second half
CURRENT_DROP_INTERVAL:
    .word 1000     # Current time between drops (changes with acceleration)

# Music related variables
base_time:      .word 0    # Base time for music timing
lastTime:       .word 0    # Track last played note
noteCount:      .word 2282   # Total number of notes in our tune
instrument:     .word 2    # MIDI instrument (1 = piano)



.text

##############################################################################
# Code
##############################################################################
	.text
	.globl main

    # Run the game.
main:
    # Initialize the game
    # Load base address and border color into registers
        lw $s0, ADDR_DSPL          # $s0 = base address for display
        lw $s1, BORDER_COLOR       # $s1 = border color

        sw $zero, base_time
        sw $zero, lastTime
        sw $zero, game_over_lastTime

        # Load margin and total units
        lw $s2, MARGIN             # $s2 = margin (8 units)
        lw $s3, TOTAL_UNITS        # $s3 = total units (64)
        
        # Calculate end_index (64 - 8 = 56)
        sub $s4, $s3, $s2          # $s4 = end_index

        # Draw the medicine bottle
        jal draw_medicine_bottle

        jal initialize_viruses

        jal draw_static_viruses

        jal draw_drmario
        
        jal draw_capsuleart

        # Generate first capsule instead of drawing directly
        jal generate_capsule

        # Enter game loop
        j game_loop

game_loop:
    # Handle music playback
    jal play_background_music
    
    # 1a. Check if key has been pressed
    lw $t0, ADDR_KBRD               # Load keyboard address
    lw $t1, 0($t0)                  # Load keyboard status
    beq $t1, 1, check_input         # If key pressed, check which key

    jal auto_drop
    
    # If no key pressed, continue with game loop
continue_game:
    # Clear previous capsule position
    lw $a0, BG_COLOR                # Load background color
    lw $a1, BG_COLOR                # Both halves should be background color
    jal draw_capsule                # Erase old capsule
    
    # Draw capsule at new position
    lw $a0, CURRENT_COLOR_1         # Load current capsule colors
    lw $a1, CURRENT_COLOR_2
    jal draw_capsule                # Draw new capsule
    
    # Sleep for a moment
    li $v0, 32                      # syscall for sleep
    lw $a0, SLEEP_TIME             # Load sleep time
    syscall
    
    j game_loop                     # Repeat game loop

# Handle keyboard input
check_input:
    lw $t2, 4($t0)                  # Load key value
    
    #check for 'p' key (ASCII 112)
    beq $t2, 112, handle_pause

    # Check for 'a' key (ASCII 97)
    beq $t2, 97, move_left
    
    # Check for 'd' key (ASCII 100)
    beq $t2, 100, move_right
    
    # Check for 's' key (ASCII 115)
    beq $t2, 115, move_down
    
    # Check for 'q' key (ASCII 113)
    beq $t2, 113, game_over
    
    # Check for 'w' key (ASCII 119)
    beq $t2, 119, rotate_capsule
    
    j continue_game

move_left:
    # Check if we can move left
    li $a0, -1              # Moving left
    jal check_horizontal_collision
    bnez $v0, continue_game # If collision detected, don't move

    jal play_move_sound
    
    # Clear old position first
    lw $a0, BG_COLOR
    lw $a1, BG_COLOR
    jal draw_capsule
    
    # Update both positions
    lw $t3, CAPSULE_POS_X1
    lw $t4, CAPSULE_POS_X2
    addi $t3, $t3, -1              # Move first half left
    addi $t4, $t4, -1              # Move second half left
    sw $t3, CAPSULE_POS_X1
    sw $t4, CAPSULE_POS_X2
    j continue_game

move_right:
    # Check if we can move right
    li $a0, 1               # Moving right
    jal check_horizontal_collision
    bnez $v0, continue_game # If collision detected, don't move
    
    jal play_move_sound
    
    # Clear old position first
    lw $a0, BG_COLOR
    lw $a1, BG_COLOR
    jal draw_capsule
    
    # Update both positions
    lw $t3, CAPSULE_POS_X1
    lw $t4, CAPSULE_POS_X2
    addi $t3, $t3, 1               # Move first half right
    addi $t4, $t4, 1               # Move second half right
    sw $t3, CAPSULE_POS_X1
    sw $t4, CAPSULE_POS_X2
    j continue_game

move_down:
    # Check if we can move down (not at bottom border)
    lw $t3, CAPSULE_POS_Y1
    lw $t4, CAPSULE_POS_Y2
    
    # Check for collision
    jal check_collision
    bnez $v0, capsule_stopped        # If collision detected, stop
    
    jal play_move_sound

    # Clear old position first
    lw $a0, BG_COLOR
    lw $a1, BG_COLOR
    jal draw_capsule
    
    # Update both positions
    lw $t3, CAPSULE_POS_Y1
    lw $t4, CAPSULE_POS_Y2
    addi $t3, $t3, 1              # Move first half down
    addi $t4, $t4, 1              # Move second half down
    sw $t3, CAPSULE_POS_Y1
    sw $t4, CAPSULE_POS_Y2
    j continue_game

capsule_stopped:
    # Draw capsule in final position
    lw $a0, CURRENT_COLOR_1
    lw $a1, CURRENT_COLOR_2
    jal draw_capsule
    
    # Check for matches
    jal check_matches
    
    # Generate new capsule
    jal generate_capsule
    j continue_game

game_over:
    jal draw_game_over
    jal play_game_over_music
    
check_restart:
    # Check for keypress
    lw $t0, ADDR_KBRD
    lw $t1, 0($t0)
    beqz $t1, check_restart
    
    # Get the key value
    lw $t2, 4($t0)
    li $t3, 0x72            # ASCII code for 'r'
    bne $t2, $t3, check_restart
    
    # Restart game
    jal erase_board
    j main

draw_game_over:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Call paint_pixels with game over data
    la $a1, gameover_x_coords
    la $a2, gameover_y_coords
    la $a3, gameover_colors
    li $a0, 2048
    jal paint_pixels
    
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

rotate_capsule:
    jal play_rotate_sound
    # Clear old position first
    lw $a0, BG_COLOR
    lw $a1, BG_COLOR
    jal draw_capsule
    
    # Load current orientation and positions
    lw $t0, CAPSULE_ORIENTATION
    lw $t1, CAPSULE_POS_X1    # First half X (fixed point)
    lw $t2, CAPSULE_POS_Y1    # First half Y (fixed point)
    
    # Increment orientation (0->1->2->3->0)
    addi $t0, $t0, 1
    li $t3, 4
    div $t0, $t3
    mfhi $t0                  # t0 = (orientation + 1) % 4
    sw $t0, CAPSULE_ORIENTATION
    
    # Update second half position based on new orientation
    beq $t0, 0, orient_right  # Horizontal right
    beq $t0, 1, orient_down   # Vertical down
    beq $t0, 2, orient_left   # Horizontal left
    beq $t0, 3, orient_up     # Vertical up
    j continue_game

orient_right:
    addi $t1, $t1, 1         # X2 = X1 + 1
    move $t2, $t2            # Y2 = Y1
    j finish_rotation

orient_down:
    move $t1, $t1            # X2 = X1
    addi $t2, $t2, 1         # Y2 = Y1 + 1
    j finish_rotation

orient_left:
    addi $t1, $t1, -1        # X2 = X1 - 1
    move $t2, $t2            # Y2 = Y1
    j finish_rotation

orient_up:
    move $t1, $t1            # X2 = X1
    addi $t2, $t2, -1        # Y2 = Y1 - 1
    j finish_rotation

finish_rotation:
    # Store new second half position
    sw $t1, CAPSULE_POS_X2
    sw $t2, CAPSULE_POS_Y2
    j continue_game

# Function: draw_medicine_bottle
# Description: Draws the medicine bottle 
draw_medicine_bottle:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Call paint_pixels with bottle data
    la $a1, bottle_x_coords
    la $a2, bottle_y_coords
    la $a3, bottle_colors
    li $a0, 1855
    jal paint_pixels
    
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

# Function: draw_capsule
# Description: Draws a capsule at the current positions.
# Inputs:
#   $a0: color for first half of the capsule
#   $a1: color for second half of the capsule
draw_capsule:
        # Draw first half of the capsule
        lw $t0, CAPSULE_POS_Y1      # Load Y1 position
        lw $t1, CAPSULE_POS_X1      # Load X1 position
        sll $t2, $t0, 8            # $t2 = row * 256
        sll $t3, $t1, 2            # $t3 = col * 4
        add $t4, $t2, $t3          # $t4 = row_offset + col_offset
        add $t4, $t4, $s0          # $t4 = base_address + offset
        sw $a0, 0($t4)             # Store color for first half of capsule

        # Draw second half of the capsule
        lw $t0, CAPSULE_POS_Y2      # Load Y2 position
        lw $t1, CAPSULE_POS_X2      # Load X2 position
        sll $t2, $t0, 8            # $t2 = row * 256
        sll $t3, $t1, 2            # $t3 = col * 4
        add $t4, $t2, $t3          # $t4 = row_offset + col_offset
        add $t4, $t4, $s0          # $t4 = base_address + offset
        sw $a1, 0($t4)             # Store color for second half of capsule

        jr $ra                     # Return from function

# Function: draw_horizontal_line
# Description: Draws a horizontal line on the bitmap display.
# Inputs:
#   $a0: row (Y-coordinate)
#   $a1: start_col (starting X-coordinate)
#   $a2: length (number of units to draw)
#   $a3: color (color value to set)

draw_horizontal_line:
        # Initialize column index and loop counter
        move $t5, $a1             # $t5 = current_col = start_col
        move $t6, $a2             # $t6 = loop counter = length

draw_horizontal_loop:
        # Check if loop counter <= 0
        blez $t6, end_draw_horizontal # If loop counter is <= 0, exit loop

        # Calculate memory address: base + (row * 256) + (col * 4)
        sll $t7, $a0, 8            # $t7 = row * 256
        sll $t8, $t5, 2            # $t8 = col * 4
        addu $t9, $t7, $t8          # $t9 = row_offset + col_offset
        addu $t9, $t9, $s0          # $t9 = base_address + offset

        # Store color at the calculated address
        sw $a3, 0($t9)             # Store border_color

        # Increment column index and decrement loop counter
        addi $t5, $t5, 1           # current_col++
        addi $t6, $t6, -1          # loop_counter--

        # Continue looping
        j draw_horizontal_loop

end_draw_horizontal:
        jr $ra                     # Return from function

# Function: draw_vertical_line
# Description: Draws a vertical line on the bitmap display.
# Inputs:
#   $a0: col (X-coordinate)
#   $a1: start_row (starting Y-coordinate)
#   $a2: length (number of units to draw)
#   $a3: color (color value to set)

draw_vertical_line:
        # Initialize row index and loop counter
        move $t5, $a1             # $t5 = current_row = start_row
        move $t6, $a2             # $t6 = loop counter = length

draw_vertical_loop:
        # Check if loop counter <= 0
        blez $t6, end_draw_vertical # If loop counter is <= 0, exit loop

        # Calculate memory address: base + (row * 256) + (col * 4)
        sll $t7, $t5, 8            # $t7 = row * 256
        sll $t8, $a0, 2            # $t8 = col * 4
        add $t9, $t7, $t8          # $t9 = row_offset + col_offset
        add $t9, $t9, $s0          # $t9 = base_address + offset

        # Store color at the calculated address
        sw $a3, 0($t9)             # Store border_color

        # Increment row index and decrement loop counter
        addi $t5, $t5, 1           # current_row++
        addi $t6, $t6, -1          # loop_counter--

        # Continue looping
        j draw_vertical_loop

end_draw_vertical:
        jr $ra                     # Return from function

check_collision:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Load current orientation
    lw $t0, CAPSULE_ORIENTATION
    
    # Branch to appropriate check based on orientation
    beq $t0, 0, check_horizontal_right  # Orientation 0: horizontal right
    beq $t0, 1, check_vertical_down     # Orientation 1: vertical down
    beq $t0, 2, check_horizontal_left   # Orientation 2: horizontal left
    beq $t0, 3, check_vertical_up       # Orientation 3: vertical up
    j no_collision                      # Shouldn't reach here
    
check_horizontal_right:
check_horizontal_left:
    # Check pixel below first half
    lw $t1, CAPSULE_POS_X1
    lw $t2, CAPSULE_POS_Y1
    addi $t2, $t2, 1          # Check one pixel below
    
    # Calculate address of pixel below first half
    sll $t3, $t2, 8           # row * 256
    sll $t4, $t1, 2           # col * 4
    add $t5, $t3, $t4         # offset = row_offset + col_offset
    add $t5, $t5, $s0         # address = base + offset
    lw $t6, 0($t5)            # Load color at this position
    
    # If pixel is not black (background), there's a collision
    lw $t7, BG_COLOR
    bne $t6, $t7, collision_detected
    
    # Check pixel below second half
    lw $t1, CAPSULE_POS_X2
    lw $t2, CAPSULE_POS_Y2
    addi $t2, $t2, 1          # Check one pixel below
    
    # Calculate address of pixel below second half
    sll $t3, $t2, 8           # row * 256
    sll $t4, $t1, 2           # col * 4
    add $t5, $t3, $t4         # offset = row_offset + col_offset
    add $t5, $t5, $s0         # address = base + offset
    lw $t6, 0($t5)            # Load color at this position
    
    # If pixel is not black (background), there's a collision
    bne $t6, $t7, collision_detected
    j no_collision
    
check_vertical_down:
    # Only need to check bottom piece (Y2)
    lw $t1, CAPSULE_POS_X2
    lw $t2, CAPSULE_POS_Y2
    addi $t2, $t2, 1          # Check one pixel below
    
    # Calculate address of pixel below bottom half
    sll $t3, $t2, 8           # row * 256
    sll $t4, $t1, 2           # col * 4
    add $t5, $t3, $t4         # offset = row_offset + col_offset
    add $t5, $t5, $s0         # address = base + offset
    lw $t6, 0($t5)            # Load color at this position
    
    # If pixel is not black (background), there's a collision
    lw $t7, BG_COLOR
    bne $t6, $t7, collision_detected
    j no_collision

check_vertical_up:
    # Need to check bottom piece (Y1)
    lw $t1, CAPSULE_POS_X1
    lw $t2, CAPSULE_POS_Y1
    addi $t2, $t2, 1          # Check one pixel below
    
    # Calculate address of pixel below bottom half
    sll $t3, $t2, 8           # row * 256
    sll $t4, $t1, 2           # col * 4
    add $t5, $t3, $t4         # offset = row_offset + col_offset
    add $t5, $t5, $s0         # address = base + offset
    lw $t6, 0($t5)            # Load color at this position
    
    # If pixel is not black (background), there's a collision
    lw $t7, BG_COLOR
    bne $t6, $t7, collision_detected
    j no_collision
    
no_collision:
    li $v0, 0                 # Return 0 for no collision
    j check_collision_end
    
collision_detected:
    li $v0, 1                 # Return 1 for collision detected
    
check_collision_end:
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

# Add this new function:
generate_capsule:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
     # Reset drop interval to base speed
    lw $t0, BASE_DROP_INTERVAL
    sw $t0, CURRENT_DROP_INTERVAL
    
    
    # Check if starting position is occupied
    li $t1, 17                # Starting X1 position
    li $t2, 11                 # Starting Y position
    
    # Calculate address of starting position
    sll $t3, $t2, 8          # row * 256
    sll $t4, $t1, 2          # col * 4
    add $t5, $t3, $t4        # offset = row_offset + col_offset
    add $t5, $t5, $s0        # address = base + offset
    lw $t6, 0($t5)           # Load color at this position
    
    # Check if position is not background color (occupied)
    lw $t7, BG_COLOR
    bne $t6, $t7,  game_over
    
    # If we get here, position is free, continue with capsule generation
    # Reset capsule to starting position
    li $t0, 31
    sw $t0, CAPSULE_POS_X1
    li $t0, 32
    sw $t0, CAPSULE_POS_X2
    li $t0, 18
    sw $t0, CAPSULE_POS_Y1
    sw $t0, CAPSULE_POS_Y2
    
    # Reset orientation to horizontal
    li $t0, 0
    sw $t0, CAPSULE_ORIENTATION
    
    # Generate random color for first half
    li $v0, 42       # Random int syscall
    li $a0, 0        # Random generator ID
    li $a1, 3        # Upper bound (0-2 for 3 colors)
    syscall          # Result in $a0
    
    # Load appropriate color for first half
    move $t8, $a0    # Save random number
    la $t0, RED_COLOR
    beq $t8, 0, load_first_color
    la $t0, BLUE_COLOR
    beq $t8, 1, load_first_color
    la $t0, YELLOW_COLOR
load_first_color:
    lw $t8, 0($t0)   # Load selected color into $t8
    
    # Generate random color for second half
    li $v0, 42       # Random int syscall
    li $a0, 0        # Random generator ID
    li $a1, 3        # Upper bound (0-2 for 3 colors)
    syscall          # Result in $a0
    
    # Load appropriate color for second half
    move $t9, $a0    # Save random number
    la $t0, RED_COLOR
    beq $t9, 0, load_second_color
    la $t0, BLUE_COLOR
    beq $t9, 1, load_second_color
    la $t0, YELLOW_COLOR
load_second_color:
    lw $t9, 0($t0)   # Load selected color into $t9
    
    # Move colors to arguments and draw capsule
    move $a0, $t8    # First color
    move $a1, $t9    # Second color
    jal draw_capsule
    
    # After selecting colors but before drawing:
    sw $t8, CURRENT_COLOR_1    # Store first color
    sw $t9, CURRENT_COLOR_2    # Store second color
    
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

check_horizontal_collision:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Load current orientation
    lw $t0, CAPSULE_ORIENTATION
    
    # Check if horizontal (0 or 2) or vertical (1 or 3)
    li $t1, 1
    beq $t0, $t1, check_horiz_vert_collision
    li $t1, 3
    beq $t0, $t1, check_horiz_vert_collision
    
check_horizontal_orient:
    # Horizontal orientation (0 or 2)
    li $t1, 0
    beq $t0, $t1, check_horiz_right_orient
    # Must be orientation 2
    bgtz $a0, check_horiz_first_half    # If moving right, check first half
    j check_horiz_second_half           # If moving left, check second half
    
check_horiz_right_orient:
    bgtz $a0, check_horiz_second_half   # If moving right, check second half
    j check_horiz_first_half            # If moving left, check first half
    
check_horiz_first_half:
    lw $t1, CAPSULE_POS_X1
    lw $t2, CAPSULE_POS_Y1
    j check_horiz_position
    
check_horiz_second_half:
    lw $t1, CAPSULE_POS_X2
    lw $t2, CAPSULE_POS_Y2
    
check_horiz_position:
    add $t1, $t1, $a0         # Add direction to X
    
    # Check boundaries
    ble $t1, 8, horiz_collision_detected
    bge $t1, 56, horiz_collision_detected
    
    # Calculate address
    sll $t3, $t2, 8           # row * 256
    sll $t4, $t1, 2           # col * 4
    add $t5, $t3, $t4         # offset = row_offset + col_offset
    add $t5, $t5, $s0         # address = base + offset
    lw $t6, 0($t5)            # Load color at this position
    
    # Check if not background
    lw $t7, BG_COLOR
    bne $t6, $t7, horiz_collision_detected
    j horiz_no_collision
    
check_horiz_vert_collision:
    # For vertical orientation, check both pieces in direction of movement
    # Check first piece
    lw $t1, CAPSULE_POS_X1
    lw $t2, CAPSULE_POS_Y1
    add $t1, $t1, $a0         # Add direction to X
    
    # Check boundaries
    ble $t1, 8, horiz_collision_detected
    bge $t1, 56, horiz_collision_detected
    
    # Calculate address for first piece
    sll $t3, $t2, 8           # row * 256
    sll $t4, $t1, 2           # col * 4
    add $t5, $t3, $t4         # offset = row_offset + col_offset
    add $t5, $t5, $s0         # address = base + offset
    lw $t6, 0($t5)            # Load color at this position
    
    # Check if not background
    lw $t7, BG_COLOR
    bne $t6, $t7, horiz_collision_detected
    
    # Check second piece
    lw $t1, CAPSULE_POS_X2
    lw $t2, CAPSULE_POS_Y2
    add $t1, $t1, $a0         # Add direction to X
    
    # Check boundaries
    ble $t1, 8, horiz_collision_detected
    bge $t1, 56, horiz_collision_detected
    
    # Calculate address for second piece
    sll $t3, $t2, 8           # row * 256
    sll $t4, $t1, 2           # col * 4
    add $t5, $t3, $t4         # offset = row_offset + col_offset
    add $t5, $t5, $s0         # address = base + offset
    lw $t6, 0($t5)            # Load color at this position
    
    # Check if not background
    lw $t7, BG_COLOR
    bne $t6, $t7, horiz_collision_detected
    j horiz_no_collision
    
horiz_no_collision:
    li $v0, 0                 # No collision
    j horiz_collision_end
    
horiz_collision_detected:
    li $v0, 1                 # Collision detected
    
horiz_collision_end:
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra


initialize_viruses:
    # Save return address and registers
    addi $sp, $sp, -8
    sw $ra, 0($sp)
    sw $s1, 4($sp)    # Counter in $s1
    
    # Initialize counter
    li $s1, 4         # Create 4 viruses
    
create_virus_loop:
    # Generate random X position (8-56)
    li $v0, 42
    li $a0, 0
    li $a1, 29        # 29 - 16 = 13 positions possible
    syscall
    addi $t1, $a0, 16  # X position in range 8-56
    
    # Generate random Y position (8-56)
    li $v0, 42
    li $a0, 0
    li $a1, 16        # only 16 rows possible
    syscall
    addi $t2, $a0, 33  # Y position in range 33-49
    
    # Get random color
    li $v0, 42        # Random int range
    li $a0, 0         # Random generator ID
    li $a1, 3         # Upper bound (exclusive)
    syscall           # Random number in $a0
    
    # Load color from array
    la $t8, VIRUS_COLORS
    sll $t9, $a0, 2   # Multiply by 4 for word offset
    add $t8, $t8, $t9
    lw $t3, 0($t8)    # Get color in $t3
    
    # Calculate display address
    sll $t4, $t2, 8   # y * 256
    sll $t5, $t1, 2   # x * 4
    add $t4, $t4, $t5 # combine offsets
    add $t4, $t4, $s0 # add to base address
    
    # Draw virus
    sw $t3, 0($t4)    # Store color at position
    
    # Decrement counter and check if done
    addi $s1, $s1, -1     # Decrement counter
    bgtz $s1, create_virus_loop  # Branch if counter > 0
    
    # Restore saved registers
    lw $ra, 0($sp)
    lw $s1, 4($sp)
    addi $sp, $sp, 8
    jr $ra

# Function to draw all static viruses
draw_static_viruses:
