# Function: play_background_music
# Description: Plays background music using MIDI syscalls  
play_background_music:
    # Save registers we'll use
    addi $sp, $sp, -24
    sw $ra, 0($sp)
    sw $t0, 4($sp)
    sw $t1, 8($sp)
    sw $t2, 12($sp)
    sw $t3, 16($sp)
    sw $t4, 20($sp)
    
    # Get current system time
    li $v0, 30
    syscall                 # Time in milliseconds in $a0
    
    # Check if base_time is initialized
    lw $t0, base_time
    bnez $t0, check_note
    
    # Initialize base_time if it's 0
    sw $a0, base_time
    j music_done

check_note:
    # Calculate elapsed time
    lw $t0, base_time
    sub $t1, $a0, $t0      # Current elapsed time
    
    # Load music state
    lw $t0, lastTime
    lw $t2, noteCount
    
    # Check if we've played all notes
    bge $t0, $t2, music_done
    
    # Calculate current note address
    sll $t2, $t0, 2        # Multiply index by 4
    
    # Load timing data
    la $t3, times
    add $t3, $t3, $t2
    lw $t4, 0($t3)         # Current note's timing
    
    # Compare with elapsed time
    bgt $t1, $t4, play_current_note
    j music_done

play_current_note:
    # Load and play note
    la $t3, notes
    add $t3, $t3, $t2
    lw $a0, 0($t3)         # Note pitch
    
    la $t3, duration
    add $t3, $t3, $t2
    lw $a1, 0($t3)         # Duration
    
    lw $a2, instrument     # Load instrument
    
    la $t3, velocity
    add $t3, $t3, $t2
    lw $a3, 0($t3)         # Velocity
    
    # Play the note
    li $v0, 31             # MIDI out syscall
    syscall
    
    # Increment music index
    lw $t0, lastTime
    addi $t0, $t0, 1
    sw $t0, lastTime

music_done:
    # Restore registers
    lw $ra, 0($sp)
    lw $t0, 4($sp)
    lw $t1, 8($sp)
    lw $t2, 12($sp)
    lw $t3, 16($sp)
    lw $t4, 20($sp)
    addi $sp, $sp, 24
    
    jr $ra

# Function: paint_pixels
# Description: Paints pixels from arrays of x, y coordinates and colors
# Parameters:
#   $a0: number of pixels to paint
#   $a1: address of x_coords array
#   $a2: address of y_coords array
#   $a3: address of colors array

paint_pixels:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Initialize counter and base address
    move $t7, $zero        # Counter = 0
    lw $t8, ADDR_DSPL     # Load display base address
    move $t9, $a0         # Store total pixels count

paint_loop:
    # Check if we're done
    beq $t7, $t9, paint_done
    
    # Load coordinates and color for current pixel
    sll $t0, $t7, 2       # Multiply counter by 4 for word offset
    
    # Get x coordinate
    add $t1, $a1, $t0     # x_coords address + offset
    lw $t1, 0($t1)        # Load x coordinate
    
    # Get y coordinate
    add $t2, $a2, $t0     # y_coords address + offset
    lw $t2, 0($t2)        # Load y coordinate
    
    # Get color
    add $t3, $a3, $t0     # colors address + offset
    lw $t3, 0($t3)        # Load color
    
    # Calculate pixel address: base + (y * 256) + (x * 4)
    sll $t4, $t2, 8       # y * 256
    sll $t5, $t1, 2       # x * 4
    add $t4, $t4, $t5     # Combine offsets
    add $t4, $t4, $t8     # Add base address
    
    # Paint the pixel
    sw $t3, 0($t4)        # Store color at calculated address
    
    # Increment counter
    addi $t7, $t7, 1
    
    j paint_loop

paint_done:
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    
    jr $ra

# Function to handle pause
handle_pause:
    # Save return address and registers we'll use
    addi $sp, $sp, -12
    sw $ra, 0($sp)
    sw $s0, 4($sp)
    sw $s1, 8($sp)
    
    # Draw PAUSED text
    la $a1, paused_x_coords
    la $a2, paused_y_coords
    li $a0, 280           # Number of pixels in PAUSED (40 x 7)
    la $a3, paused_colors
    jal paint_pixels

pause_loop:
    jal play_background_music # keeps playing bg music while paused
    
    # Check for keyboard input
    lw $t0, ADDR_KBRD    # Load keyboard address
    lw $t1, 0($t0)       # Get keyboard ready bit
    beq $t1, $zero, pause_loop  # If no input, keep waiting
    
    jal play_background_music
    
    # Get the key that was pressed
    lw $t0, 4($t0)       # Get the key value
    lw $t1, PAUSE_KEY
    bne $t0, $t1, pause_loop  # If not 'p', keep waiting
    
    # Clear PAUSED text by drawing black rectangles
    la $a1, paused_x_coords
    la $a2, paused_y_coords
    li $a0, 280          # Same number of pixels
    li $t0, 0x000000     # Black color
    
    # Create temporary array of black colors on stack
    addi $sp, $sp, -1120  # Make room for 280 words (280 * 4 = 1120 bytes)
    move $s0, $sp        # Save start of our temp array
    move $s1, $zero      # Counter
    
fill_black_loop:
    sw $t0, 0($s0)      # Store black color
    addi $s0, $s0, 4    # Next word
    addi $s1, $s1, 1    # Increment counter
    blt $s1, 280, fill_black_loop
    
    # Draw black over PAUSED text
    move $a3, $sp       # Use our black color array
    jal paint_pixels
    
    # Clean up stack
    addi $sp, $sp, 1120
    
    # Restore registers and return
    lw $ra, 0($sp)
    lw $s0, 4($sp)
    lw $s1, 8($sp)
    addi $sp, $sp, 12
    jr $ra

# Auto drop function
auto_drop:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Get current system time
    li $v0, 30     # syscall 30: get system time
    syscall        # time in milliseconds returned in $a0
    
    # Check if enough time has passed
    lw $t0, LAST_AUTO_DROP_TIME
    lw $t1, CURRENT_DROP_INTERVAL
    sub $t2, $a0, $t0    # Time elapsed since last drop
    blt $t2, $t1, auto_drop_end  # If not enough time passed, return
    
    # Time to drop! Update last drop timestamp
    sw $a0, LAST_AUTO_DROP_TIME
    
    # Decrease current interval by 15% (multiply by 0.85)
    lw $t0, CURRENT_DROP_INTERVAL
    mul $t0, $t0, 85     # Multiply by 85 (100 - 15)
    div $t0, $t0, 100    # Divide by 100 to get 85%
    sw $t0, CURRENT_DROP_INTERVAL
    
    # Move piece down
    jal move_down
    
auto_drop_end:
    # Restore return address and return
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

check_matches:
    # Save registers
    addi $sp, $sp, -8
    sw $ra, 0($sp)      # Return address STORE
    sw $t0, 4($sp)      # Temp STORE
    
    # Check from first half
    lw $a2, CAPSULE_POS_X1    # Load x1
    lw $a3, CAPSULE_POS_Y1    # Load y1
    lw $t0, CURRENT_COLOR_1   # Load color1
    lw $t7, CURRENT_COLOR_1   # new implementation of color
    addi $sp, $sp, -4         # Make space for color
    sw $t0, 0($sp)           # Store color on stack
    
    # Check horizontal (right)
    li $a0, 1    # direction x = 1
    li $a1, 0    # direction y = 0
    jal check_direction
    
    # Check vertical (down)
    li $a0, 0    # direction x = 0
    li $a1, 1    # direction y = 1
    jal check_direction
    
    addi $sp, $sp, 4    # Remove color from stack
    
    # Now check from second half
    lw $a2, CAPSULE_POS_X2    # Load x2
    lw $a3, CAPSULE_POS_Y2    # Load y2
    lw $t0, CURRENT_COLOR_2   # Load color2
    lw $t7, CURRENT_COLOR_2   # new implementation of color
    addi $sp, $sp, -4         # Make space for color
    sw $t0, 0($sp)           # Store color on stack
    
    # Check horizontal (right)
    li $a0, 1    # direction x = 1
    li $a1, 0    # direction y = 0
    jal check_direction
    
    # Check vertical (down)
    li $a0, 0    # direction x = 0
    li $a1, 1    # direction y = 1
    jal check_direction
    
    addi $sp, $sp, 4    # Remove color from stack
    
    # Restore registers
    lw $ra, 0($sp)      # Return address LOAD
    lw $t0, 4($sp)      # Temp LOAD
    addi $sp, $sp, 8
    jr $ra

check_all_directions:
    # Save registers
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Check horizontal (right)
    li $a0, 1    # direction x = 1
    li $a1, 0    # direction y = 0
    jal check_direction
    
    # Check horizontal (left)
    li $a0, -1   # direction x = -1
    li $a1, 0    # direction y = 0
    jal check_direction
    
    # Check vertical (down)
    li $a0, 0    # direction x = 0
    li $a1, 1    # direction y = 1
    jal check_direction
    
    # Check vertical (up)
    li $a0, 0    # direction x = 0
    li $a1, -1   # direction y = -1
    jal check_direction
    
    # Restore registers
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

check_direction:
    # $a0 = direction x
    # $a1 = direction y
    # $s2 = color to match (passed from caller)
    
    # Save registers
    addi $sp, $sp, -24
    sw $ra, 0($sp)      # Return address STORE
    sw $t0, 4($sp)      # Match counter STORE
    sw $t1, 8($sp)      # Current x STORE
    sw $t2, 12($sp)     # Current y STORE
    sw $t3, 16($sp)     # Display offset STORE
    sw $t4, 20($sp)     # Base address STORE
    
    # Initialize counter
    li $t0, 1           # Start at 1 (we already have the first tile)
    
    # Load starting position from a2 and a3
    move $t1, $a2  # Current x
    move $t2, $a3  # Current y
    move $t8, $a2  # Storing current x here asw cos i cant figure out where its being modified
    move $t9, $a3  # Storing current y here asw cos i cant figure out where its being modified
    lw $t4, ADDR_DSPL       # Display base address
    
check_next:
    # Calculate next position
    add $t1, $t1, $a0    # Next x
    add $t2, $t2, $a1    # Next y
    
    # Boundary check
    # li $t3, 8           # Left boundary
    # blt $t1, $t3, not_match
    # li $t3, 55          # Right boundary
    # bgt $t1, $t3, not_match
    # li $t3, 8           # Top boundary
    # blt $t2, $t3, not_match
    # li $t3, 55          # Bottom boundary
    # bgt $t2, $t3, not_match
    
    # Calculate display address
    sll $t3, $t2, 8     # y * 256
    sll $t5, $t1, 2     # x * 4
    add $t3, $t3, $t5   # combine offsets
    add $t3, $t3, $t4   # add to base address
    
    # Load color at position
    lw $v0, 0($t3)      # Get color
    
    # Compare with target color
    bne $v0, $t7, not_match
    
    # Increment counter
    addi $t0, $t0, 1
    
    # Check if we have 4 matches
    beq $t0, 4, found_match
    
    # Continue checking
    j check_next
    
not_match:
    li $v0, 0    # Return false
    j check_direction_done
    
found_match:
    # Clear the matched tiles
    jal play_match_sound
    jal clear_matched_tiles
    li $v0, 1    # Return true
    
check_direction_done:
    # Restore registers
    lw $ra, 0($sp)      # Return address LOAD
    lw $t0, 4($sp)      # Match counter LOAD
    lw $t1, 8($sp)      # Current x LOAD
    lw $t2, 12($sp)     # Current y LOAD
    lw $t3, 16($sp)     # Display offset LOAD
    lw $t4, 20($sp)     # Base address LOAD
    addi $sp, $sp, 24
    jr $ra
    # Restore registers
    lw $ra, 0($sp)      # Return address LOAD
    lw $t0, 4($sp)      # Match counter LOAD
    lw $t1, 8($sp)      # Current x LOAD
    lw $t2, 12($sp)     # Current y LOAD
    lw $t3, 16($sp)     # Display offset LOAD
    lw $t4, 20($sp)     # Color temp LOAD
    addi $sp, $sp, 24
    jr $ra
    # Restore registers
    lw $ra, 0($sp)      # Return address LOAD
    lw $t0, 4($sp)      # Match counter LOAD
    lw $t1, 8($sp)      # Current x LOAD
    lw $t2, 12($sp)     # Current y LOAD
    lw $t3, 16($sp)     # Display offset LOAD
    lw $t4, 20($sp)     # Base address LOAD
    addi $sp, $sp, 24
    jr $ra
    # Restore registers
    lw $ra, 0($sp)      # Return address LOAD
    lw $t0, 4($sp)      # Match counter LOAD
    lw $t1, 8($sp)      # Current x LOAD
    lw $t2, 12($sp)     # Current y LOAD
    lw $t3, 16($sp)     # Display offset LOAD
    lw $t4, 20($sp)     # Color temp LOAD
    lw $s0, 24($sp)     # Base address LOAD (restore original $s0)
    addi $sp, $sp, 28
    jr $ra
get_color_at_position:
    # $t1 = x position
    # $t2 = y position
    # Returns color in $v0
    
    # Calculate display address
    sll $t3, $t2, 8    # y * 256
    sll $t4, $t1, 2    # x * 4
    add $t3, $t3, $t4  # combine offsets
    lw $s0, ADDR_DSPL
    add $t3, $t3, $s0  # add to base address
    
    # Load color
    lw $v0, 0($t3)
    jr $ra

clear_matched_tiles:
    # Save registers
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Reset to starting position
    move $t1, $t8    # x position
    move $t2, $t9    # y position
    li $t0, 0        # counter
    
clear_loop:
    # Calculate display address
    sll $t3, $t2, 8    # y * 256
    sll $t4, $t1, 2    # x * 4
    add $t3, $t3, $t4  # combine offsets
    lw $t4, ADDR_DSPL
    add $t3, $t3, $t4  # add to base address
    
    # Clear tile
    lw $t4, BG_COLOR
    sw $t4, 0($t3)
    
    # Move to next position
    add $t1, $t1, $a0    # Next x
    add $t2, $t2, $a1    # Next y
    
    # Increment counter
    addi $t0, $t0, 1
    blt $t0, 4, clear_loop
    
    # Restore registers
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

# Add to your functions section
play_game_over_music:
    # Save registers
    addi $sp, $sp, -24
    sw $ra, 0($sp)
    sw $s0, 4($sp)    # Note index
    sw $s1, 8($sp)    # Total notes
    sw $s2, 12($sp)   # Start time
    sw $s3, 16($sp)   # Current time
    sw $s4, 20($sp)   # Base time
    
    # Initialize
    li $s0, 0                         # Start with first note
    lw $s1, game_over_noteCount       # Total number of notes
    
    # Get start time
    li $v0, 30
    syscall
    move $s2, $a0                     # Store start time
    move $s4, $a0                     # Base time for relative timing
    
game_over_loop:
    # Get current time
    li $v0, 30
    syscall
    sub $s3, $a0, $s4                 # Current relative time
    
    # Load target time for current note
    la $t0, game_over_times
    sll $t1, $s0, 2                   # Index * 4
    add $t0, $t0, $t1
    lw $t0, 0($t0)                     # Target time for this note
    
    # If we haven't reached the time for this note, keep waiting
    blt $s3, $t0, game_over_loop
    
    # Time to play the note
    # Load note parameters
    la $t0, game_over_notes
    la $t1, game_over_duration
    la $t2, game_over_instruments
    la $t3, game_over_velocity
    
    sll $t4, $s0, 2                   # Index * 4
    
    # Get parameters for syscall
    add $t5, $t0, $t4
    lw $a0, 0($t5)                     # Pitch
    
    add $t5, $t1, $t4
    lw $a1, 0($t5)                     # Duration
    
    add $t5, $t2, $t4
    lw $a2, 0($t5)                     # Instrument
    
    add $t5, $t3, $t4
    lw $a3, 0($t5)                     # Volume
    
    # Play the note
    li $v0, 31
    syscall
    
    # Move to next note
    addi $s0, $s0, 1
    blt $s0, $s1, game_over_loop
    
    # Wait for last note to finish
    li $v0, 32
    li $a0, 2100                      # Wait for the last note duration
    syscall
    
    # Restore registers
    lw $ra, 0($sp)
    lw $s0, 4($sp)
    lw $s1, 8($sp)
    lw $s2, 12($sp)
    lw $s3, 16($sp)
    lw $s4, 20($sp)
    addi $sp, $sp, 24
    jr $ra

erase_board:
    # Save registers
    addi $sp, $sp, -16
    sw $ra, 0($sp)
    sw $s0, 4($sp)
    sw $s1, 8($sp)
    sw $s2, 12($sp)
    
    # Get base display address
    lw $s2, ADDR_DSPL
    
    # Loop through each pixel of the entire display
    li $s0, 0      # start y at 0
erase_row_loop:
    li $s1, 0      # start x at 0
erase_col_loop:
    # Calculate pixel address
    mul $t0, $s0, 256  # y * display width
    sll $t1, $s1, 2    # x * 4 (bytes per pixel)
    add $t0, $t0, $t1  # combine offsets
    add $t0, $s2, $t0  # add to base address
    
    # Draw background color
    lw $t1, BG_COLOR
    sw $t1, 0($t0)
    
    # Next column
    addi $s1, $s1, 1
    li $t0, 64     # display width
    blt $s1, $t0, erase_col_loop
    
    # Next row
    addi $s0, $s0, 1
    li $t0, 128    # display height
    blt $s0, $t0, erase_row_loop
    
    # Restore registers
    lw $ra, 0($sp)
    lw $s0, 4($sp)
    lw $s1, 8($sp)
    lw $s2, 12($sp)
    addi $sp, $sp, 16
    jr $ra

play_move_sound:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Play a short beep
    li $v0, 31
    li $a0, 40        # Pitch (higher pitch = 80)
    li $a1, 50       # Duration (100ms)
    li $a2, 121       # Instrument (121 = sound effects)
    li $a3, 50       # Volume (max = 127)
    syscall
    
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

play_rotate_sound:
    # Save return address
    addi $sp, $sp, -4
    sw $ra, 0($sp)
    
    # Play a short beep with different characteristics
    li $v0, 31
    li $a0, 80       # Higher pitch than move sound (100 vs 80)
    li $a1, 75        # Shorter duration (50ms vs 100ms)
    li $a2, 10       # Same instrument (sound effects)
    li $a3, 127       # Max volume
    syscall
    
    # Restore return address
    lw $ra, 0($sp)
    addi $sp, $sp, 4
    jr $ra

play_match_sound:
    # Save return address and arguments
    addi $sp, $sp, -20
    sw $ra, 0($sp)
    sw $a0, 4($sp)
    sw $a1, 8($sp) 
    sw $a2, 12($sp)
    sw $a3, 16($sp)
    
    # First note (lowest)
    li $v0, 31
    li $a0, 60        # Start with lower pitch
    li $a1, 50        # Short duration
    li $a2, 1         # Instrument 1 (piano)
    li $a3, 127       # Max volume
    syscall
    
    # Tiny delay
    li $v0, 32
    li $a0, 20        # 20ms delay
    syscall
    
    # Second note (middle)
    li $v0, 31
    li $a0, 72        # Higher pitch
    li $a1, 50        # Same duration
    li $a2, 1         # Same instrument
    li $a3, 127       # Max volume
    syscall
    
    # Tiny delay
    li $v0, 32
    li $a0, 20        # 20ms delay
    syscall
    
    # Third note (highest)
    li $v0, 31
    li $a0, 84        # Highest pitch
    li $a1, 100       # Slightly longer duration
    li $a2, 1         # Same instrument
    li $a3, 127       # Max volume
    syscall
    
    # Restore arguments and return address
    lw $ra, 0($sp)
    lw $a0, 4($sp)
    lw $a1, 8($sp)
    lw $a2, 12($sp)
    lw $a3, 16($sp)
    addi $sp, $sp, 20
    jr $ra